"""Read the supplied original's launcher leaf transforms; never execute it."""
from pathlib import Path
from inspect_original import Original


def main():
    original = Original()
    lines = [
        '// Generated by game/tools/import_launcher_visual.py from the supplied original.',
        '// MissleLauncher.initSprites / updateAnimation: use these 60-frame leaf poses.',
        '#pragma once',
        '#include "engine/core/geometry/vector2.h"',
        '#include <algorithm>',
        '#include <array>',
        'namespace game::play {',
        'struct LauncherLeafPose {elysia::core::Vector2 position;float rotation;};',
    ]
    for name, address in [('Right', 0x1a0dfc), ('Left', 0x1a10cc)]:
        lines.append(f'// ARM table at 0x{address:x}: local Y-up points and clockwise degrees.')
        lines.append(f'inline constexpr std::array<LauncherLeafPose,60> kLauncher{name}Leaf{{{{')
        for frame in range(60):
            x, y, rotation = original.unpack('<3f', address + frame * 12)
            def literal(value):
                number = format(value, '.6g')
                return number + ('.0f' if '.' not in number and 'e' not in number else 'f')
            lines.append('    {{' + literal(x) + ',' + literal(y) + '},' + literal(rotation) + '},')
        lines.append('}};')
    lines.extend([
        'inline LauncherLeafPose launcher_leaf_pose(double seconds,bool left) {',
        '    const auto frame=static_cast<std::size_t>(std::clamp(seconds*60.,0.,59.));',
        '    return (left?kLauncherLeftLeaf:kLauncherRightLeaf)[frame];',
        '}',
        '}',
    ])
    target = Path(__file__).resolve().parents[1] / 'gameplay/launcher_visual.h'
    target.write_text('\n'.join(lines) + '\n', encoding='utf8')
    print(target)


if __name__ == '__main__':
    main()
